def get_avatar_ascii(avatar_path, cols=34):
    if os.path.exists(avatar_path):
        try:
            from PIL import Image
            import numpy as np

            ASCII_RAMP = " .:-=+*#%@"
            img = Image.open(avatar_path).convert("L")
            w, h = img.size
            min_dim = min(w, h)
            left = (w - min_dim) // 2
            top = (h - min_dim) // 2
            img = img.crop((left, top, left + min_dim, top + min_dim))
            
            rows = int(cols * 0.55)
            img = img.resize((cols, rows))
            
            arr = np.array(img)
            lines = []
            for r in range(rows):
                line = ""
                for c in range(cols):
                    val = arr[r, c]
                    idx = int((val / 255.0) * (len(ASCII_RAMP) - 1))
                    line += ASCII_RAMP[idx]
                lines.append(line)
            return lines
        except Exception as e:
            print(f"Note: Avatar image processing skipped ({e}). Using default ASCII art.")

